import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @returns {string} - Plain-text invoice
 */
export function renderInvoiceText(invoice) {
  // Get invoice number or DRAFT
  const invoiceNumber = invoice.number ?? 'DRAFT';

  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  // Build lines
  const lines = [invoiceNumber, customerName];

  // Add invoice lines
  let hasDiscounts = false;
  for (const line of invoice.lines) {
    const lineTotalResult = lineTotal(line);
    if (lineTotalResult.ok) {
      const lineAmount = lineTotalResult.value;

      let lineStr = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(lineAmount)}`;

      if (line.discountPercent) {
        hasDiscounts = true;
        const lineDiscountResult = lineDiscount(line);
        if (lineDiscountResult.ok) {
          const discount = lineDiscountResult.value;
          lineStr += ` (${line.discountPercent}% off: -${formatEuros(discount)})`;
        }
      }

      lines.push(lineStr);
    }
  }

  // Add totals
  const totalsResult = invoiceTotals(invoice);
  if (totalsResult.ok) {
    const totals = totalsResult.value;
    if (hasDiscounts) {
      lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
      lines.push(`Discount: -${formatEuros(totals.discount)}`);
    }
    if (totals.vat > 0) {
      lines.push(`VAT: ${formatEuros(totals.vat)}`);
    }
    lines.push(`Total: ${formatEuros(totals.total)}`);
  }

  return lines.join('\n');
}

